import json, yaml, re

with open('/home/ubuntu/.claude-account-1/projects/-home-ubuntu--agent-ml-research-be-idea-gen-0515-2-projects-importance-margin-vla-compress--claude-sessions-reviewer-4a8dfe57/facf884a-4c89-4504-a643-7782795bbc10/tool-results/mcp-agent-ml-research-read_registry-1779467963756.txt', 'r') as f:
    data = json.load(f)

result_str = data['result']
parsed = yaml.safe_load(result_str)
experiments = parsed['data']['experiments']

def extract_model(eid, spec):
    model = spec.get('model_name', '')
    if model:
        return model
    eid_lower = eid.lower()
    if 'pi05' in eid_lower or 'pi0.5' in eid_lower:
        return 'pi0.5'
    elif 'xvla' in eid_lower:
        return 'xvla'
    elif 'smolvla' in eid_lower:
        return 'smolvla'
    elif 'openvla' in eid_lower:
        return 'openvla'
    return ''

def extract_suite(eid, spec, metrics):
    suite = spec.get('suite', '')
    if not suite and isinstance(metrics, dict):
        suite = metrics.get('suite', '')
    if not suite:
        eid_lower = eid.lower()
        if 'object' in eid_lower:
            suite = 'object'
        elif 'goal' in eid_lower:
            suite = 'goal'
        elif 'long' in eid_lower or 'libero_10' in eid_lower:
            suite = 'long'
        elif 'spatial' in eid_lower:
            suite = 'spatial'
    return suite

def extract_prune_mode(eid, spec):
    cmd = spec.get('command', '')
    # From command
    m = re.search(r'--prune_mode\s+(\S+)', cmd)
    if m:
        return m.group(1)
    eid_lower = eid.lower()
    if 'l2norm' in eid_lower:
        return 'l2norm'
    elif 'random' in eid_lower:
        return 'random'
    elif 'attention' in eid_lower or 'attn' in eid_lower:
        return 'attention'
    elif 'baseline' in eid_lower or 'none' in eid_lower:
        return 'none/baseline'
    elif 'acis' in eid_lower:
        return 'acis'
    elif 'vtc' in eid_lower or 'vtr' in eid_lower:
        return 'vtc/vtr'
    return ''

def extract_keep_ratio(eid, spec):
    cmd = spec.get('command', '')
    m = re.search(r'--keep_ratio\s+([\d.]+)', cmd)
    if m:
        return m.group(1)
    # From exp_id
    m = re.search(r'k0?(\d+)', eid)
    if m:
        val = m.group(1)
        if len(val) <= 2:
            return f"0.{val}"
        else:
            return f"0.{val}"
    return ''

def get_success_rate(metrics):
    if not isinstance(metrics, dict):
        return ''
    sr = metrics.get('success_rate', '')
    if sr == '':
        sr = metrics.get('avg_success_rate', '')
    return sr

# Collect all DONE and RUNNING
results = []
for eid, exp in sorted(experiments.items()):
    status = exp.get('status', 'UNKNOWN')
    if status not in ('DONE', 'RUNNING'):
        continue
    spec = exp.get('spec', {})
    metrics = exp.get('metrics', {})
    conclusion = exp.get('conclusion', '')

    model = extract_model(eid, spec)
    suite = extract_suite(eid, spec, metrics)
    prune_mode = extract_prune_mode(eid, spec)
    keep_ratio = extract_keep_ratio(eid, spec)
    seed = spec.get('seed', '')
    sr = get_success_rate(metrics)

    conc_str = ''
    if isinstance(conclusion, str):
        conc_str = conclusion[:200].replace('\n', ' ')
    elif isinstance(conclusion, dict):
        conc_str = str(conclusion)[:200]

    results.append({
        'exp_id': eid,
        'status': status,
        'model': model,
        'suite': suite,
        'prune_mode': prune_mode,
        'keep_ratio': keep_ratio,
        'seed': str(seed),
        'success_rate': str(sr),
        'conclusion': conc_str
    })

# Print DONE
print("=" * 220)
print("SECTION 1: ALL DONE EXPERIMENTS ({} total)".format(sum(1 for r in results if r['status'] == 'DONE')))
print("=" * 220)
print(f"{'exp_id':<65} {'model':<10} {'suite':<12} {'prune':<12} {'keep_r':<8} {'seed':<6} {'sr':<10} {'conclusion'}")
print("-" * 220)
for r in results:
    if r['status'] == 'DONE':
        print(f"{r['exp_id']:<65} {r['model']:<10} {r['suite']:<12} {r['prune_mode']:<12} {r['keep_ratio']:<8} {r['seed']:<6} {r['success_rate']:<10} {r['conclusion']}")

print()
print("=" * 220)
print("SECTION 2: ALL RUNNING EXPERIMENTS ({} total)".format(sum(1 for r in results if r['status'] == 'RUNNING')))
print("=" * 220)
print(f"{'exp_id':<65} {'model':<10} {'suite':<12} {'prune':<12} {'keep_r':<8} {'seed':<6} {'sr':<10} {'conclusion'}")
print("-" * 220)
for r in results:
    if r['status'] == 'RUNNING':
        print(f"{r['exp_id']:<65} {r['model']:<10} {r['suite']:<12} {r['prune_mode']:<12} {r['keep_ratio']:<8} {r['seed']:<6} {r['success_rate']:<10} {r['conclusion']}")

